import {HEROES,ORDERS,RULES,createGame,validateState,heldOrders,availableHeroes,legalTargets,legalAttacks,legalDefenses,previewAttack,previewDefense,applyAttack,applyDefense,selectAttack,selectDefense} from './engine.js';
import {icon,portrait,castleArt,landscape} from './art.js';
const $=id=>document.getElementById(id),heroIds=['kora','ilda','neris'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={left:'Sol burç',main:'Ana kale',right:'Sağ kule'},types={stone:'Taş',arrow:'Ok',sound:'Yankı',steel:'Çelik',universal:'Her tür'},colors={stone:'#dfc093',arrow:'#a1d5b1',sound:'#c0aff2',steel:'#edb18e'},symbols={stone:'stone',arrow:'arrow',sound:'sound',steel:'tactic',universal:'shield'};
const cardRules={volley:'Hızlı ve doğrudan baskı.',ram:'En güçlü doğrudan darbe.',catapult:'Önceki hedefe +18 hasar.',mist:'8 savunmayı deler.',banner:'Çıktığın kaleye +12 siper.'};
const STORE='kale-muhafizlari-v3';let settings={sound:false,trainingEnabled:false,bestTraining:0,seenIntro:false};
let state,selectedHero=null,selectedOrder=null,selectedTarget=null,selectedDefense='brace',busy=false,generation=0,modalGeneration=0,trainingFrame=0,trainingSession=null,finishShown=false,audioContext,centerResult=null,storageAvailable=true;
const timers=new Set(),reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
function readStore(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
const saved=readStore(STORE),oldSaved=readStore('kale-muhafizlari-v2')||readStore('kale-muhafizlari-v1');
if(saved?.settings||oldSaved?.settings){const s=saved?.settings||oldSaved.settings;settings={sound:s.sound===true,trainingEnabled:saved?s.trainingEnabled===true:false,bestTraining:Math.max(0,Math.min(3,Math.trunc(Number(s.bestTraining)||0))),seenIntro:saved?.settings?.seenIntro===true};}
function freshGame(){return createGame({seed:`orders-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,firstSide:state?.firstSide?(state.firstSide==='player'?'enemy':'player'):'random',trainingEnabled:settings.trainingEnabled,training:{power:settings.bestTraining}});}
try{validateState(saved?.state);state=saved.state;}catch{state=freshGame();}
let previousNeutral=state.neutralOrder;
function persist(){try{localStorage.setItem(STORE,JSON.stringify({settings,state}));}catch{storageAvailable=false;}}
function schedule(fn,delay){const token=generation;const id=setTimeout(()=>{timers.delete(id);if(token!==generation)return;if($('modal').open){schedule(fn,120);return;}fn();},delay);timers.add(id);}
function cancelTimers(){generation++;for(const t of timers)clearTimeout(t);timers.clear();$('effects').innerHTML='';centerResult=null;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3300);}
function sound(kind){if(!settings.sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const t=audioContext.currentTime,tones=kind==='win'?[330,440,554,660]:kind==='guard'?[440,660]:kind==='hit'?[100,65]:kind==='exchange'?[262,392]:[330];tones.forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=kind==='hit'?'triangle':'sine';o.frequency.setValueAtTime(f,t+i*.08);g.gain.setValueAtTime(0,t+i*.08);g.gain.linearRampToValueAtTime(.05,t+i*.08+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.08+.24);o.connect(g);g.connect(audioContext.destination);o.start(t+i*.08);o.stop(t+i*.08+.26);});}catch{}}
function soundIcon(){$('sound-button').innerHTML=icon(settings.sound?'volume':'mute');$('sound-button').setAttribute('aria-label',settings.sound?'Sesi kapat':'Sesi aç');$('sound-button').setAttribute('aria-pressed',String(settings.sound));}
$('landscape').innerHTML=landscape;$('help-button').innerHTML=icon('help');$('settings-button').innerHTML=icon('settings');$('close-modal').innerHTML=icon('close');soundIcon();
const activeHeroes=(side)=>availableHeroes(state,side).filter(h=>h.available);
function stationed(side,id){return heroIds.filter(h=>state.heroes[side][h].castleId===id);}
function orderColor(id){const c=colors[ORDERS[id].type];return `--card-color:${c};--card-glow:${c}22`;}
function actualAttack(){if(!selectedHero||!selectedOrder||!selectedTarget)return null;return legalAttacks(state,'player').find(a=>a.heroId===selectedHero&&a.orderId===selectedOrder&&a.targetId===selectedTarget)||null;}
function attackValue(id){if(!selectedHero)return ORDERS[id].damage;const h=HEROES[selectedHero];return ORDERS[id].damage+(h.type===ORDERS[id].type?3:0)+(selectedHero==='kora'&&ORDERS[id].type==='stone'?state.trainingBySide.player:0)+(id==='catapult'&&selectedTarget&&selectedTarget===state.lastOwnTarget.player?18:0);}
function renderCastles(side){const playerChoice=side==='player'&&!busy&&state.phase==='playerAttack',targetChoice=side==='enemy'&&!busy&&state.phase==='playerAttack'&&selectedOrder;const legal=legalTargets(state,side==='enemy'?'player':'enemy').map(c=>c.id);return state.castles[side].map(c=>{const native=c.id==='left'?'kora':c.id==='right'?'ilda':'neris',station=stationed(side,c.id),chosen=side==='player'&&selectedHero&&state.heroes.player[selectedHero].castleId===c.id,targeted=side==='enemy'&&selectedTarget===c.id&&state.phase==='playerAttack',incoming=side==='player'&&state.phase==='playerDefense'&&state.pendingAttack?.targetId===c.id,locked=c.id==='main'&&!legal.includes(c.id)&&c.hp>0&&state.phase!=='finished',selectable=playerChoice&&activeHeroes(side).some(h=>h.castleId===c.id);let marker=locked?`${icon('lock')} ANA KALE`:c.cover?`${icon('shield')} +12 SİPER`:'';let markerClass=c.cover?'ward':'';if(chosen&&state.phase==='playerAttack'){marker=`${HEROES[selectedHero].name.toLocaleUpperCase('tr')} SEÇİLİ`;markerClass='gold';}if(targeted){marker='SEÇİLEN HEDEF';markerClass='red';}if(incoming){marker='SALDIRI BURAYA';markerClass='red';}
return `<button class="castle-button ${c.id==='main'?'main':''} ${c.hp<=0?'fallen':''} ${selectable?'selectable':''} ${chosen?'selected':''} ${targetChoice&&!locked&&c.hp>0?'targetable':''} ${targeted?'targeted':''} ${incoming?'incoming':''}" data-castle="${c.id}" data-side="${side}" ${c.hp<=0||(!selectable&&!targetChoice)?'disabled':''} aria-label="${side==='player'?'Senin':'Rakip'} ${names[c.id]}, ${c.hp}/${c.maxHp} can. ${station.map(h=>HEROES[h].name).join(', ')}${locked?'. Bir yan kale yıkılmadan hedeflenemez.':''}${c.cover?'. Sonraki darbeye 12 siper.':''}">${marker?`<span class="castle-state ${markerClass}">${marker}</span>`:''}${castleArt(side,c.id==='main',c.hp<=0,native)}${c.hp>0?station.map((h,i)=>`<span class="hero-badge ${i?'extra':''} ${state.heroes[side][h].retreatRounds?'retreat':''}">${portrait(h)}</span>`).join(''):''}<span class="castle-label"><b>${c.hp<=0?'Yıkıldı':names[c.id]}</b><small>${c.hp>0?HEROES[native].name:''}</small></span><span class="castle-hp"><span class="hp-track"><span class="hp-fill" style="width:${c.hp/c.maxHp*100}%"></span></span><span class="hp-number">${c.hp}<span class="hp-total">/${c.maxHp}</span></span></span></button>`;}).join('');}
function renderEnemyHand(){$('enemy-hand').innerHTML=heldOrders(state,'enemy').map(o=>`<button class="enemy-card ${o.committed?'committed':''}" style="${orderColor(o.id)}" data-order-info="${o.id}" aria-label="Rakip emri ${o.name}. ${o.damage} ${types[o.type]} hasarı. ${types[o.guardType]} saldırısına ${o.guardBlock} savunma.${o.committed?' Sonraki saldırıda bekliyor.':''}">${icon(symbols[o.type])}<strong>${o.name}</strong><small>${o.damage} ${types[o.type]} · ${icon('shield').replace('class="icon"','class="icon" style="width:9px;height:9px"')} ${types[o.guardType]}</small></button>`).join('');const o=ORDERS[state.neutralOrder];$('neutral-order').style.cssText=orderColor(o.id);$('neutral-order').innerHTML=`<span class="eyebrow">ORTADAKİ EMİR</span><strong>${icon(symbols[o.type])}${o.name}</strong><small>Saldırınca eline geçer ↔</small>`;if(previousNeutral!==state.neutralOrder&&!reducedMotion.matches){$('neutral-order').animate?.([{transform:'rotate(-2deg) translateY(-12px) scale(.9)',filter:'brightness(1.8)',opacity:.3},{transform:'rotate(-2deg) translateY(0) scale(1)',filter:'brightness(1)',opacity:1}],{duration:550,easing:'cubic-bezier(.2,.8,.2,1)'});}previousNeutral=state.neutralOrder;}
function setCenter(){const c=$('battle-center'),p=state.pendingAttack;c.className='battle-center';if(centerResult){c.classList.add('result');c.innerHTML=`<span class="eyebrow">HAMLE SONUCU</span><strong>${esc(centerResult.title)}</strong><small>${esc(centerResult.detail)}</small>`;return;}if(state.phase==='playerDefense'||state.phase==='aiDefense'){c.classList.add('incoming');c.innerHTML=`<span class="eyebrow">${state.phase==='playerDefense'?'GELEN SALDIRI':'SENİN SALDIRIN'}</span><strong>${icon(symbols[p.type])}${ORDERS[p.orderId].name} · ${p.damage}</strong><small>${HEROES[p.heroId].name} → ${names[p.targetId]}${p.pierce?' · 8 siper deler':''}</small>`;}else if(state.phase==='aiAttack'){c.innerHTML=`<span class="eyebrow">KIZIL SANCAK</span><strong>Rakip düşünüyor.</strong><small>Elindeki iki emri sen de görüyorsun.</small>`;}else if(state.phase==='finished'){c.innerHTML=`<span class="eyebrow">DÜELLO BİTTİ</span><strong>${state.winner==='player'?'Sancak senin.':'Kalen düştü.'}</strong><small>${state.turnIndex} saldırı · Her rövanşta ilk sıra değişir.</small>`;}else{c.innerHTML=`<span class="eyebrow">${state.round}. TUR · SIRA SENDE</span><strong>${!selectedHero?'Bir kaleden başla.':!selectedOrder?'Emrini seç.':!selectedTarget?'Hedefini göster.':'Hamlen hazır.'}</strong><small>${selectedTarget?`${HEROES[selectedHero].name} → ${names[selectedTarget]}`:state.committedOrder.player?`${ORDERS[state.committedOrder.player].name} savundu; şimdi diğer emri kullan.`:'Kendi kalen → bir emir → rakip kale'}</small>`;}}
function renderPlayerCards(){const defense=state.phase==='playerDefense';$('player-hand').innerHTML=heldOrders(state,'player').map(o=>{let pv=null;if(defense)pv=previewDefense(state,{orderId:o.id});const committed=!defense&&o.committed,selected=defense?selectedDefense===o.id:selectedOrder===o.id;const value=defense?pv.blocked:attackValue(o.id);return `<button class="order-card ${selected?'selected':''} ${committed?'committed':''} ${defense?(pv.matching?'match':'mismatch'):''}" style="${orderColor(o.id)}" data-order="${o.id}" ${busy||committed||!['playerAttack','playerDefense'].includes(state.phase)?'disabled':''} aria-pressed="${selected}" aria-label="${o.name}. ${defense?`${pv.blocked} engeller, ${pv.damage} hasar kalır. Sonraki saldırıda bu emir bekler.`:`${value} ${types[o.type]} hasarı. ${cardRules[o.id]}`}${committed?' Savunmada kullanıldı, bu saldırıda bekliyor.':''}"><span class="card-top">${icon(symbols[o.type])}<span class="card-damage">${value}<small>${defense?'ENGELLER':'HASAR'}</small></span></span><h2>${o.name}</h2><span class="card-rule">${defense?(pv.matching?`${pv.localBonus?'+4 yerel koruma. ':''}Diğer emirle saldıracaksın.`:'Tür uyuşmuyor. Kart 0 korur.'):cardRules[o.id]}</span><span class="card-guard">${icon('shield')}${types[o.guardType]} karşısında <b>${o.guardBlock}</b></span>${committed?'<span class="committed-label">SAVUNDU · BU SALDIRIDA BEKLER</span>':''}</button>`;}).join('');}
function renderPanel(){const defense=state.phase==='playerDefense',attack=state.phase==='playerAttack';$('phase-label').textContent=defense?'SAVUNMA SIRASI':attack?'SALDIRI SIRASI':state.phase==='finished'?'DÜELLO TAMAM':'RAKİBİN SIRASI';$('command-title').textContent=defense?'Koru. Ama yarını da düşün.':attack?'Gücünü kime bırakacaksın?':state.phase==='finished'?(state.winner==='player'?'Krallık güvende.':'Yeni bir plan kur.'):'Emirler el değiştiriyor.';$('turn-seal').textContent=String(state.round).padStart(2,'0');$('hand-label').textContent=defense?'SAVUNMA YÜZÜNÜ KULLAN':'SENİN İKİ EMRİN';$('hand-hint').textContent=defense?'Kullandığın emir sonraki saldırıda bekler.':'Oynadığın emir ortaya geçer.';renderPlayerCards();
if(defense){const p=state.pendingAttack,pv=previewDefense(state,{orderId:selectedDefense});$('selection-path').innerHTML=`${icon('shield')}<span><b>${names[p.targetId]}</b><small>${p.damage} ${types[p.type]} hasarı geliyor.</small></span><span class="path-arrow">↓</span>`;$('guard-fallback').innerHTML=`<button class="brace-button ${selectedDefense==='brace'?'selected':''}" data-defense="brace" ${busy?'disabled':''}>${icon('shield')} Basit siper · 8 <small>İki emrini de saldırıya sakla</small></button>`;$('move-preview').innerHTML=`<div class="preview-line"><span>${p.damage} saldırı − ${pv.blocked} koruma</span><strong>${pv.damage} net hasar</strong></div><div class="preview-line"><span>${names[p.targetId]} canı</span><strong class="${pv.castleFell?'warning':''}">${state.castles.player.find(c=>c.id===p.targetId).hp} → ${pv.hpAfter}</strong></div><div class="exchange-preview">${icon('exchange')} Sonraki saldırın: <b>${pv.nextAttackOrders.map(id=>ORDERS[id].name).join(' veya ')}</b></div>`;$('action-button').disabled=busy;$('action-button').innerHTML=`${icon('shield')} ${selectedDefense==='brace'?'Siper al · emirleri sakla':ORDERS[selectedDefense].name+' ile savun'}`;$('action-note').textContent=pv.coverBlock?`Kaledeki +12 siper bu darbede tüketilir.${p.pierce?' Sis, toplam korumanın 8’ini deler.':''}`:selectedDefense==='brace'?'Kart değişmez. Sonraki saldırında iki seçeneğin de açık.':!pv.matching?'Tür uyuşmuyor: kartın koruması 0; yine de sonraki saldırıda bekler.':'Savunmada kart değişmez. Seçtiğin emir sonraki saldırında bekler.';return;}
$('guard-fallback').innerHTML='';if(attack){const a=actualAttack(),pv=a?previewAttack(state,a):null;$('selection-path').innerHTML=selectedHero?`${portrait(selectedHero)}<span><b>${HEROES[selectedHero].name}</b><small>${selectedOrder?ORDERS[selectedOrder].name:'Bir emir seç'}${selectedTarget?' → '+names[selectedTarget]:''}</small></span><span class="path-arrow">→</span>`:`${icon('flag')}<span><b>Kendi kalene dokun</b><small>Sonra emrini ve hedefini seç.</small></span><span class="path-arrow">→</span>`;
if(pv){const best=Math.min(...pv.possibleBlocks.map(d=>d.damage)),brace=pv.possibleBlocks.find(d=>d.orderId==='brace');$('move-preview').innerHTML=`<div class="preview-line"><span>${pv.baseDamage}${pv.nativeBonus?' + '+pv.nativeBonus+' uzmanlık':''}${pv.trainingBonus?' + '+pv.trainingBonus+' talim':''}${pv.repeatBonus?' +18 odak':''}</span><strong>${pv.damage} ham hasar</strong></div><div class="preview-line"><span>Rakibin iyi savunması / basit siper</span><strong>${best} / ${brace.damage} net</strong></div><div class="exchange-preview">${icon('exchange')} Alırsın: <b>${ORDERS[pv.nextReceivedOrder].name}</b> · Ortaya: <b>${ORDERS[selectedOrder].name}</b></div>`;}else{$('move-preview').innerHTML=`<div class="preview-line"><span>${selectedOrder?`${ORDERS[selectedOrder].name} · ${types[ORDERS[selectedOrder].type]}`:'Beş emir. Hepsi açık.'}</span><strong>${selectedOrder?attackValue(selectedOrder)+' hasar':'2 sende · 2 rakipte'}</strong></div><p class="preview-detail">${!selectedHero?'Saldırıyı başlatacak muhafızını savaş alanından seç.':!selectedOrder?'Emrin saldırı ve savunma yüzü farklıdır.':'Hesabı görmek için rakip kaleye dokun.'}</p><div class="exchange-preview">${icon('exchange')} Saldırınca alacağın emir: <b>${ORDERS[state.neutralOrder].name}</b></div>`;}
$('action-button').disabled=busy||!a;$('action-button').innerHTML=!selectedHero?'Önce kendi kaleni seç':!selectedOrder?'Şimdi bir emir seç':!selectedTarget?'Şimdi rakip kaleyi seç':`${icon(symbols[a.type])} ${ORDERS[a.orderId].name} · Hamleyi oyna`;$('action-note').textContent=selectedOrder==='banner'?'Sancak, saldırının çıktığı kaleye tek darbeye karşı +12 siper kurar.':selectedOrder==='catapult'?`Önceki hedefin: ${state.lastOwnTarget.player?names[state.lastOwnTarget.player]:'yok'}. Aynı hedefe mancınık +18 vurur.`:'Oynadığın emir ortaya geçer. Rakip kendi emrini oynayınca onu alır.';
}else{$('selection-path').innerHTML=`${icon('exchange')}<span><b>${centerResult?.title||'Sahadaki hamleyi izle.'}</b><small>Gizli kart yok. Gizli güç yok.</small></span>`;$('move-preview').innerHTML=`<div class="preview-line"><span>Ortadaki emir</span><strong>${ORDERS[state.neutralOrder].name}</strong></div><p class="preview-detail">${state.phase==='finished'?'Bir rövanşta başlangıç sırası değişir.':'Kale canları darbe ulaştığında değişir.'}</p>`;$('action-button').disabled=state.phase!=='finished';$('action-button').innerHTML=state.phase==='finished'?`${icon('refresh')} Rövanş · sıra değişsin`:'Hamle sürüyor…';$('action-note').textContent=state.phase==='finished'?'Yeni düello yeni açık emir dağılımıyla başlar.':'Kararların için süre sınırı yok.';}}
function render(){const f=document.activeElement;const focusKey=f?.dataset?.order?`[data-order="${f.dataset.order}"]`:f?.dataset?.castle?`[data-side="${f.dataset.side}"][data-castle="${f.dataset.castle}"]`:f?.dataset?.defense?`[data-defense="${f.dataset.defense}"]`:null;if(selectedOrder&&state.committedOrder.player===selectedOrder)selectedOrder=null;if(selectedOrder&&!state.hands.player.includes(selectedOrder))selectedOrder=null;if(selectedHero&&!activeHeroes('player').some(h=>h.id===selectedHero))selectedHero=null;if(selectedTarget&&!legalTargets(state,'player').some(c=>c.id===selectedTarget))selectedTarget=null;$('round-label').textContent=`TUR ${state.round}`;$('enemy-castles').innerHTML=renderCastles('enemy');$('player-castles').innerHTML=renderCastles('player');renderEnemyHand();setCenter();renderPanel();persist();if(focusKey){const next=document.querySelector(focusKey);if(next&&!next.disabled)next.focus?.({preventScroll:true});}}
function point(side,id){const target=$('arena').querySelector(`[data-side="${side}"][data-castle="${id}"]`),a=$('arena').getBoundingClientRect(),b=target.getBoundingClientRect();return{x:b.left+b.width/2-a.left,y:b.top+b.height*.48-a.top};}
function resolveAnimated(attack,next){busy=true;render();const from=point(attack.side,attack.sourceId),to=point(attack.side==='player'?'enemy':'player',attack.targetId),color=colors[attack.type],duration=reducedMotion.matches?50:600;const projectile=document.createElement('span');projectile.className='projectile';projectile.style.cssText=`left:${from.x-15}px;top:${from.y-15}px;color:${color}`;projectile.innerHTML=icon(symbols[attack.type]);$('effects').appendChild(projectile);if(projectile.animate)projectile.animate([{transform:'translate(0,0) scale(.5)',opacity:0},{offset:.12,opacity:1},{transform:`translate(${to.x-from.x}px,${to.y-from.y}px) scale(1.2)`,opacity:1}],{duration,easing:'cubic-bezier(.35,.05,.65,.85)',fill:'forwards'});schedule(()=>{projectile.remove();state=next;const event=state.lastEvent;centerResult={title:event.hpLost?`${event.hpLost} hasar${event.castleFell?' · Kale düştü':''}`:'Saldırı durduruldu.',detail:`${event.incoming} saldırı − ${event.blocked} koruma${event.coverConsumed?' · Siper tüketildi':''}`};render();const side=attack.side==='player'?'enemy':'player';const target=$('arena').querySelector(`[data-side="${side}"][data-castle="${attack.targetId}"]`);target?.classList.add(event.hpLost?'hit':'guarded');$('effects').innerHTML=`<span class="impact-ring" style="left:${to.x}px;top:${to.y}px;color:${event.hpLost?color:'#7ee1cf'}"></span><span class="damage-float ${event.hpLost?'':'blocked'}" style="left:${to.x}px;top:${to.y-15}px">${event.hpLost?'-'+event.hpLost:'SİPER'}</span>`;sound(event.hpLost?'hit':'guard');$('live-status').textContent=`${names[attack.targetId]}: ${event.hpLost} hasar. ${event.castleFell?'Kale yıkıldı.':''}`;schedule(()=>{$('effects').innerHTML='';centerResult=null;selectedOrder=null;selectedTarget=null;selectedDefense='brace';busy=false;drive();},reducedMotion.matches?70:670);},duration);}
function drive(){if(state.phase==='finished'){busy=false;render();if(!finishShown){finishShown=true;sound(state.winner==='player'?'win':'hit');schedule(showFinish,450);}return;}if(state.phase==='aiDefense'){busy=true;render();schedule(()=>{const attack=state.pendingAttack;const next=applyDefense(state,'enemy',selectDefense(state,'enemy'));resolveAnimated(attack,next);},reducedMotion.matches?60:600);}else if(state.phase==='aiAttack'){busy=true;render();schedule(()=>{state=applyAttack(state,'enemy',selectAttack(state,'enemy'));busy=false;selectedDefense='brace';sound('exchange');render();$('live-status').textContent=`${ORDERS[state.pendingAttack.orderId].name}, ${state.pendingAttack.damage} hasar, ${names[state.pendingAttack.targetId]} hedefte. Savunmanı seç.`;},reducedMotion.matches?60:850);}else{busy=false;render();}}
function takeAction(){if(busy||$('modal').open)return;if(state.phase==='finished'){newGame();return;}if(state.phase==='playerAttack'){const a=actualAttack();if(!a)return;try{state=applyAttack(state,'player',a);busy=true;sound('exchange');drive();}catch(e){toast(e.message);}}else if(state.phase==='playerDefense'){try{const p=state.pendingAttack,next=applyDefense(state,'player',{orderId:selectedDefense,revision:state.revision});busy=true;resolveAnimated(p,next);}catch(e){toast(e.message);}}}
function newGame(){cancelTimers();closeModal();state=freshGame();selectedHero=null;selectedOrder=null;selectedTarget=null;selectedDefense='brace';busy=false;finishShown=false;render();toast(`İlk hamle ${state.firstSide==='player'?'sende':'rakipte'}. Beş emir yeniden dağıtıldı.`);drive();}
$('arena').addEventListener('click',e=>{const b=e.target.closest('[data-castle]');if(!b||b.disabled||busy||state.phase!=='playerAttack')return;const id=b.dataset.castle;if(b.dataset.side==='player'){const hs=activeHeroes('player').filter(h=>h.castleId===id),at=hs.findIndex(h=>h.id===selectedHero);if(!hs.length)return;selectedHero=hs[(at+1)%hs.length].id;selectedTarget=null;sound('select');render();}else{if(!selectedHero){toast('Önce kendi kalenden bir muhafız seç.');return;}if(!selectedOrder){toast('Önce elindeki iki emirden birini seç.');return;}if(!legalTargets(state,'player').some(c=>c.id===id)){toast('Ana kaleye ulaşmak için önce bir yan kaleyi yık.');return;}selectedTarget=id;sound('select');render();}});
$('player-hand').addEventListener('click',e=>{const b=e.target.closest('[data-order]');if(!b||b.disabled||busy)return;if(state.phase==='playerDefense')selectedDefense=b.dataset.order;else if(state.phase==='playerAttack'){selectedOrder=b.dataset.order;selectedTarget=null;}sound('select');render();});$('guard-fallback').addEventListener('click',e=>{if(e.target.closest('[data-defense]')&&!busy){selectedDefense='brace';render();}});$('action-button').addEventListener('click',takeAction);
$('sound-button').addEventListener('click',()=>{settings.sound=!settings.sound;soundIcon();persist();if(settings.sound)sound('select');});$('new-button').addEventListener('click',()=>openModal(`<div class="eyebrow">YENİ DÜELLO</div><h2>Bu savaşı bırak?</h2><p>Mevcut düello sıfırlanır. Talim derecen korunur. İlk hamle bu kez ${state.firstSide==='player'?'rakibin':'senin'} olur.</p><button class="primary-button" data-modal-action="new">Yeni düelloya başla</button><div class="modal-actions"><button class="secondary-button" data-modal-action="close">Mevcut düelloya dön</button></div>`));
function openModal(html){modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;$('modal-content').innerHTML=html;const h=$('modal-content').querySelector('h2');if(h)h.id='modal-title';if(!$('modal').open)$('modal').showModal();}
function closeModal(){modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;$('modal').close();}
$('close-modal').addEventListener('click',closeModal);$('modal').addEventListener('cancel',()=>{modalGeneration++;cancelAnimationFrame(trainingFrame);trainingSession=null;});$('modal').addEventListener('click',e=>{if(e.target!==$('modal'))return;const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();});
function help(){openModal(`<div class="eyebrow">BEŞ EMİR · BİR KRALLIK</div><h2>Gücün el değiştirir.</h2><p>İki emir sende, iki emir rakipte, biri ortada. Hepsini görebilirsin. En güçlü hamle, her zaman en iyi hamle değildir.</p><div class="help-steps"><div class="help-step"><span>1</span><div><strong>Kaleni, emrini, hedefini seç.</strong><p>Saldırdığın emir ortaya geçer; ortadaki emir senin olur. Rakip kendi emrini oynadıktan sonra senin bıraktığın gücü alır. Ona ne bıraktığını düşün.</p></div></div><div class="help-step"><span>2</span><div><strong>Savunma yarınki seçimini değiştirir.</strong><p>Kartın altındaki kalkan türü gelen saldırıyla eşleşirse korur. Savunmada kart değişmez; kullandığın emir hemen sonraki saldırında bekler. Diğer emrinle saldırırsın. Basit siper 8 korur, iki seçeneği de açık tutar.</p></div></div><div class="help-step"><span>3</span><div><strong>Kalelerin bir planı olsun.</strong><p>Mancınık önceki saldırınla aynı hedefe +18 vurur. Sancak çıktığı kaleye tek darbeye +12 siper kurar. Sis 8 korumayı deler. Bir yan kaleyi yık, ana kaleyi aç; ana kaleyi düşür, kazan.</p></div></div></div><p class="modal-note">Enerji ve süreli bekleme yok. Kora taşta, İlda okta, Neris yankıda +3 uzmanlık verir. Yerel muhafız +4 savunur; en iyi uygun muhafız otomatik seçilir. Yıkılan yan kalenin muhafızı bir saldırı dinlenir, sonra ana kaleye katılır. İlk sıra her rövanşta değişir.</p><button class="primary-button" data-modal-action="close">Meydana dön ${icon('chevron')}</button>`);}
$('help-button').addEventListener('click',help);
function orderInfo(id){const o=ORDERS[id];openModal(`<div class="eyebrow">AÇIK EMİR · ${types[o.type].toLocaleUpperCase('tr')}</div><h2>${o.name}</h2><p>${o.rule}</p><p class="modal-note">Saldırı: ${o.damage} ham hasar.<br>Savunma yüzü: ${types[o.guardType]} saldırısına ${o.guardBlock} koruma; yerel muhafız +4.<br>Savunmada kullanırsan sonraki saldırında bu emir bekler. Başka türü savunursa kart 0 korur.</p><button class="primary-button" data-modal-action="close">Meydana dön</button>`);}
$('enemy-hand').addEventListener('click',e=>{const b=e.target.closest('[data-order-info]');if(b)orderInfo(b.dataset.orderInfo);});
function settingsModal(){openModal(`<div class="eyebrow">KENDİ TEMPOUNDA</div><h2>Düello ayarları</h2><div class="settings-row"><div><strong>Kora’nın kalıcı talimi</strong><small>En iyi derece +${settings.bestTraining}. Yalnız Kora’nın taş emrine eklenir; savunmayı etkilemez. Yeni düelloda uygulanır. Önceki sürümün derecesi korunur.</small></div><label class="toggle-target" for="bonus-toggle"><input id="bonus-toggle" type="checkbox" ${settings.trainingEnabled?'checked':''} aria-label="Yeni düelloda Kora talim bonusunu uygula"></label></div><div class="settings-row"><div><strong>Ses efektleri</strong><small>Yalnız bu cihazda saklanır.</small></div><label class="toggle-target" for="sound-toggle"><input id="sound-toggle" type="checkbox" ${settings.sound?'checked':''} aria-label="Ses efektlerini aç"></label></div><p class="modal-note">Bu düelloda Kora: Mancınık ${25+state.trainingBySide.player}, aynı önceki hedefe ${43+state.trainingBySide.player}. Diğer emirler talim bonusu almaz.<br>İlk sıra: ${state.firstSide==='player'?'sen':'rakip'}. Bir sonraki düelloda değişir.</p><button class="primary-button" data-modal-action="new">Bu ayarlarla yeni düello</button><div class="modal-actions"><button class="secondary-button" data-modal-action="stories">Muhafızların hikâyesi</button><button class="secondary-button danger-button" data-modal-action="reset-confirm">Cihazdaki ilerlemeyi temizle</button></div><p class="modal-note">Hesap, ödeme ve çevrimiçi veri aktarımı yok. ${storageAvailable?'Düello bu tarayıcıda saklanır.':'Kayıt alanı kullanılamıyor; sekme kapanınca ilerleme kaybolabilir.'}</p>`);$('bonus-toggle').addEventListener('change',e=>{settings.trainingEnabled=e.target.checked;persist();});$('sound-toggle').addEventListener('change',e=>{settings.sound=e.target.checked;soundIcon();persist();if(settings.sound)sound('select');});}
$('settings-button').addEventListener('click',settingsModal);
function stories(){openModal(`<div class="eyebrow">ÜÇ MUHAFIZ · TEK SANCAK</div><h2>Göğün son kaleleri.</h2><div class="story-hero">${portrait('kora')}<div><h3>Kora</h3><p>Bulutların üzerindeki burçları elleriyle inşa eden taş ustası. Yıktığı her duvar için bir köprü kurmaya söz verdi.</p><em>“Sağlam dur. Gerisini ben hallederim.”</em></div></div><div class="story-hero">${portrait('ilda')}<div><h3>İlda</h3><p>Rüzgâr yollarının eski habercisi. Kuleler arasındaki en kısa yolu bilir; okları, haberlerinden de hızlıdır.</p><em>“Rüzgâr fısıldadı. Ben duydum.”</em></div></div><div class="story-hero">${portrait('neris')}<div><h3>Neris</h3><p>Uçan adaları bir arada tutan çanların koruyucusu. Bir yankıyla siper kurar, bir sessizlikle yeni planını saklar.</p><em>“Doğru an, en güçlü sestir.”</em></div></div><button class="primary-button" data-modal-action="close">Meydana dön</button>`);}
$('stories-button').addEventListener('click',stories);$('log-button').addEventListener('click',()=>openModal(`<div class="eyebrow">SON HAMLELER</div><h2>Emirlerin izi.</h2><ol class="log-list">${[...state.log].reverse().map(t=>`<li>${esc(t)}</li>`).join('')}</ol><button class="primary-button" data-modal-action="close">Meydana dön</button>`));
function showFinish(){if(state.phase!=='finished')return;openModal(`<div class="win-content">${icon(state.winner==='player'?'flag':'shield')}<div class="eyebrow">${state.winner==='player'?'SANCAGIN YÜKSELİYOR':'BİR SONRAKİ PLANIN'}</div><h2>${state.winner==='player'?'Gökyüzü senin.':'Bu son hamlen değil.'}</h2><p>${state.winner==='player'?'Rakibin ana kalesi düştü. Doğru emri doğru anda bıraktın.':'Ana kalen düştü. Rövanşta savunurken hangi saldırıdan vazgeçtiğini ve rakibine hangi emri bıraktığını düşün.'}</p><p class="modal-note">${state.turnIndex} saldırı · ${state.castles.player.filter(c=>c.hp>0).length} dost kale ayakta.<br>Bir sonraki düelloda ilk hamle ${state.firstSide==='player'?'rakibin':'senin'}.</p><button class="primary-button" data-modal-action="new">${icon('refresh')} Rövanş · sıra değişsin</button><div class="modal-actions" style="justify-content:center"><button class="secondary-button" data-modal-action="close">Savaş alanına bak</button></div></div>`);}
function training(){openModal(`<div class="training-header">${portrait('kora')}<div><div class="eyebrow">KORA’NIN TALİM ALANI</div><h2>Taşa yön ver.</h2><p>Altın bölgenin ortasında vur. Üç atış, bir kalıcı derece.</p></div></div><div class="training-range"><span class="training-zone"></span><span id="training-marker" class="training-marker"></span></div><div class="training-shots" id="training-shots"><span class="training-shot">1</span><span class="training-shot">2</span><span class="training-shot">3</span></div><button class="primary-button" id="training-hit">${icon('stone')} Şimdi vur!</button><p id="training-feedback" role="status" aria-live="polite" style="text-align:center">Hazır olduğunda ilk atışını yap.</p><p class="modal-note">En iyi derece +0–3 kalıcı taş saldırısı sağlar. Yalnız Kora’nın Mancınık emrine uygulanır: 25 → en çok 28. Ayarlardan açılır, yeni düelloda geçerli olur.</p>`);trainingSession={start:performance.now(),position:.5,scores:[],lock:false};const session=trainingSession,sessionModal=modalGeneration;const tick=now=>{if(trainingSession!==session||modalGeneration!==sessionModal||!$('modal').open)return;session.position=.5+Math.sin((now-session.start)/(580-session.scores.length*70))*.47;const marker=$('training-marker');if(marker)marker.style.left=session.position*100+'%';trainingFrame=requestAnimationFrame(tick);};trainingFrame=requestAnimationFrame(tick);$('training-hit').addEventListener('click',trainingHit);}
function trainingHit(){const s=trainingSession;if(!s||s.lock)return;s.lock=true;const d=Math.abs(s.position-.5),score=d<=.08?100:d<=.2?65:25;s.scores.push(score);sound(score===100?'guard':'hit');$('training-shots').innerHTML=[0,1,2].map(i=>`<span class="training-shot ${i<s.scores.length?'done':''}">${s.scores[i]===100?'✦':s.scores[i]===65?'✓':s.scores[i]===25?'·':i+1}</span>`).join('');$('training-feedback').textContent=score===100?'Tam isabet!':score===65?'İyi atış.':'Hedefi sıyırdı. Yeniden odaklan.';if(s.scores.length===3){cancelAnimationFrame(trainingFrame);const avg=s.scores.reduce((a,b)=>a+b,0)/3,tier=avg>=90?3:avg>=65?2:avg>=35?1:0;settings.bestTraining=Math.max(settings.bestTraining,tier);persist();trainingSession=null;$('training-hit').disabled=true;const token=modalGeneration;setTimeout(()=>{if(token!==modalGeneration||!$('modal').open||!$('training-hit'))return;openModal(`<div class="eyebrow">TALİM TAMAMLANDI</div><h2>${tier?'Taş sözünü dinliyor.':'Bir daha deneyelim.'}</h2><div class="star-row">${'★'.repeat(tier)}${'☆'.repeat(3-tier)}</div><p style="text-align:center">Bu talim +${tier} · En iyi derecen +${settings.bestTraining}<br>Kora’nın Mancınığı: ${25+settings.bestTraining} hasar.</p><p class="modal-note">Talim yalnız Kora’nın taş emrini geliştirir. Mevcut düellonun sayıları değişmez.</p><button class="primary-button" data-modal-action="training-new">Gelişimi aç · yeni düello</button><div class="modal-actions"><button class="secondary-button" data-modal-action="training">Yeniden talim</button><button class="secondary-button" data-modal-action="close">Mevcut düelloya dön</button></div>`);},700);}else setTimeout(()=>{if(trainingSession===s)s.lock=false;},300);}
$('training-button').addEventListener('click',training);
$('modal-content').addEventListener('click',e=>{const a=e.target.closest('[data-modal-action]')?.dataset.modalAction;if(!a)return;if(a==='close')closeModal();else if(a==='new')newGame();else if(a==='stories')stories();else if(a==='settings')settingsModal();else if(a==='training')training();else if(a==='training-new'){settings.trainingEnabled=true;newGame();}else if(a==='reset-confirm')openModal(`<div class="eyebrow">YENİ BİR SAYFA</div><h2>İlerleme temizlensin mi?</h2><p>Bu oyunun kaydı, talim derecesi ve ayarları bu tarayıcıdan silinir. Geri alınamaz. Başka sitelerin verilerine dokunulmaz.</p><button class="primary-button" data-modal-action="reset">Evet, ilerlemeyi temizle</button><div class="modal-actions"><button class="secondary-button" data-modal-action="settings">Vazgeç</button></div>`);else if(a==='reset'){for(const k of [STORE,'kale-muhafizlari-v2','kale-muhafizlari-v1'])try{localStorage.removeItem(k);}catch{}settings={sound:false,trainingEnabled:false,bestTraining:0,seenIntro:true};soundIcon();newGame();toast('Oyun ilerlemesi temizlendi.');}});
window.addEventListener('pagehide',persist);document.querySelector('.brand').addEventListener('click',e=>e.preventDefault());
render();if(['aiAttack','aiDefense'].includes(state.phase))drive();else if(state.phase==='finished')finishShown=true;
if(!settings.seenIntro){settings.seenIntro=true;persist();openModal(`<div class="eyebrow">KALE MUHAFIZLARI · III</div><h2>Oynadığın güç,<br>bir gün karşına çıkar.</h2><p>Beş açık emir iki krallık arasında dolaşıyor. Birini kullan, ortadakini al. Güçlü saldırın rakibinin sonraki planına dönüşebilir.</p><div class="help-steps"><div class="help-step"><span>1</span><div><strong>Kendi kalen → emir → rakip kale</strong><p>Bütün seçimler ve saldırı aynı savaş alanında.</p></div></div><div class="help-step"><span>2</span><div><strong>Savunmak bir seçimden vazgeçmektir.</strong><p>Savunmada kullandığın kart, hemen sonraki saldırında bekler.</p></div></div></div><p class="modal-note">İlk hamle ${state.firstSide==='player'?'sende':'rakipte'}. Rövanşta sıra değişir.${oldSaved?' Önceki talim derecen korundu; bu yeni düelloda bonus varsayılan olarak kapalı.':''}</p><button class="primary-button" data-modal-action="close">Göğe yüksel ${icon('chevron')}</button><div class="modal-actions"><button class="secondary-button" data-modal-action="stories">Muhafızları tanı</button></div>`);}
if(!storageAvailable)toast('Bu tarayıcı ilerlemeyi kaydedemiyor. Açık sekmede oynayabilirsin.');
